alter table public.web_push_subscriptions add column if not exists staff_user_id uuid references auth.users(id) on delete cascade;
alter table public.web_push_subscriptions drop constraint if exists web_push_one_owner;
alter table public.web_push_subscriptions add constraint web_push_one_owner check(num_nonnulls(guardian_id,instructor_id,staff_user_id)=1);
create index if not exists web_push_staff_active_idx on public.web_push_subscriptions(staff_user_id) where active;
alter table public.notifications add column if not exists staff_user_id uuid references auth.users(id) on delete cascade;
create table if not exists public.manager_notification_settings(user_id uuid primary key references auth.users(id) on delete cascade,new_request boolean not null default true,updated_at timestamptz not null default now());
alter table public.manager_notification_settings enable row level security;revoke all on public.manager_notification_settings from public,anon,authenticated;
create or replace function private.current_manager_user_id() returns uuid language sql stable security definer set search_path='' as $$select id from public.app_users where id=auth.uid() and role in('manager','system_admin')$$;
revoke all on function private.current_manager_user_id() from public,anon;grant execute on function private.current_manager_user_id() to authenticated;
create or replace function public.get_my_manager_request_notification_settings() returns table(new_request boolean,push_devices integer) language sql stable security definer set search_path='' as $$select coalesce(s.new_request,true),(select count(*)::integer from public.web_push_subscriptions w where w.staff_user_id=u.id and w.active) from public.app_users u left join public.manager_notification_settings s on s.user_id=u.id where u.id=auth.uid() and u.role in('manager','system_admin')$$;
revoke all on function public.get_my_manager_request_notification_settings() from public,anon;grant execute on function public.get_my_manager_request_notification_settings() to authenticated;
create or replace function public.save_my_manager_request_notification_settings(p_new_request boolean) returns void language plpgsql security definer set search_path='' as $$declare v_user uuid:=private.current_manager_user_id();begin if v_user is null then raise exception 'Недостаточно прав';end if;insert into public.manager_notification_settings(user_id,new_request,updated_at) values(v_user,p_new_request,now()) on conflict(user_id) do update set new_request=excluded.new_request,updated_at=now();end$$;
revoke all on function public.save_my_manager_request_notification_settings(boolean) from public,anon;grant execute on function public.save_my_manager_request_notification_settings(boolean) to authenticated;
create or replace function public.disable_all_my_manager_push_subscriptions() returns void language plpgsql security definer set search_path='' as $$declare v_user uuid:=private.current_manager_user_id();begin if v_user is null then raise exception 'Недостаточно прав';end if;update public.web_push_subscriptions set active=false,updated_at=now() where staff_user_id=v_user;end$$;
revoke all on function public.disable_all_my_manager_push_subscriptions() from public,anon;grant execute on function public.disable_all_my_manager_push_subscriptions() to authenticated;
create or replace function public.register_my_push_subscription(p_endpoint text,p_p256dh text,p_auth_secret text,p_user_agent text default null,p_device_name text default null) returns uuid language plpgsql security definer set search_path='' as $$declare v_guardian uuid:=private.current_guardian_id();v_instructor uuid;v_staff uuid;v_id uuid;begin if auth.uid() is null then raise exception 'Нужно войти';end if;if v_guardian is null then select instructor_id into v_instructor from public.app_users where id=auth.uid() and instructor_id is not null;end if;if v_guardian is null and v_instructor is null then select id into v_staff from public.app_users where id=auth.uid() and role in('manager','system_admin');end if;if v_guardian is null and v_instructor is null and v_staff is null then raise exception 'Профиль не поддерживает Push';end if;insert into public.web_push_subscriptions(guardian_id,instructor_id,staff_user_id,endpoint,p256dh,auth_secret,user_agent,device_name,active,updated_at) values(v_guardian,v_instructor,v_staff,p_endpoint,p_p256dh,p_auth_secret,left(p_user_agent,1000),left(p_device_name,120),true,now()) on conflict(endpoint) do update set guardian_id=excluded.guardian_id,instructor_id=excluded.instructor_id,staff_user_id=excluded.staff_user_id,p256dh=excluded.p256dh,auth_secret=excluded.auth_secret,user_agent=excluded.user_agent,device_name=excluded.device_name,active=true,last_error=null,updated_at=now() returning id into v_id;return v_id;end$$;
revoke all on function public.register_my_push_subscription(text,text,text,text,text) from public,anon;grant execute on function public.register_my_push_subscription(text,text,text,text,text) to authenticated;
create or replace function private.notify_managers_about_new_request() returns trigger language plpgsql security definer set search_path='' as $$declare recipient record;begin for recipient in select u.id from public.app_users u left join public.manager_notification_settings s on s.user_id=u.id where u.role in('manager','system_admin') and coalesce(s.new_request,true) and exists(select 1 from public.web_push_subscriptions w where w.staff_user_id=u.id and w.active) loop insert into public.notifications(staff_user_id,channel,event_type,payload,status,attempts,scheduled_for,idempotency_key,created_at,updated_at) values(recipient.id,'push','instructor_schedule_event',jsonb_build_object('title','Новая заявка · АкваВнуково','body',new.child_name||case when new.phone is not null then ' · '||new.phone else '' end,'url','/?manager_requests=1','event','new_request'),'pending',0,now(),'manager:new-request:'||new.id||':'||recipient.id,now(),now()) on conflict(idempotency_key) where idempotency_key is not null do nothing;end loop;return new;end$$;
drop trigger if exists notify_managers_about_new_request on public.requests;
create trigger notify_managers_about_new_request after insert on public.requests for each row when(new.status='new') execute function private.notify_managers_about_new_request();
create or replace function public.claim_instructor_schedule_events(p_limit integer default 100) returns table(notification_id uuid,channel text,title text,body text,target_url text,chat_id bigint,endpoint text,p256dh text,auth_secret text) language plpgsql security definer set search_path='' as $$begin perform public.queue_tomorrow_instructor_events();return query with candidates as(select n.id from public.notifications n where n.event_type='instructor_schedule_event' and n.status in('pending','failed') and n.scheduled_for<=now() and n.attempts<3 order by n.created_at for update skip locked limit greatest(1,least(p_limit,500))),claimed as(update public.notifications n set status='processing',attempts=n.attempts+1,updated_at=now(),last_error=null from candidates c where n.id=c.id returning n.*) select c.id,c.channel,c.payload->>'title',c.payload->>'body',c.payload->>'url',(c.payload->>'chat_id')::bigint,w.endpoint,w.p256dh,w.auth_secret from claimed c left join public.web_push_subscriptions w on c.channel='push' and w.active and((c.instructor_id is not null and w.instructor_id=c.instructor_id)or(c.staff_user_id is not null and w.staff_user_id=c.staff_user_id));end$$;
revoke all on function public.claim_instructor_schedule_events(integer) from public,anon,authenticated;grant execute on function public.claim_instructor_schedule_events(integer) to service_role;
select pg_notify('pgrst','reload schema');
